Hub.UpdateSidePanelPosition = function(self)
	local panel = self.State.SidePanel;
	local main = self.State.MainFrame;
	if not (panel and main) then
		return;
	end
	local halfMainW = main.Size.X.Offset / 2;
	local panelW = panel.Size.X.Offset;
	local cam = self.Services.Workspace.CurrentCamera;
	local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720);
	local rightPos = main.Position.X.Offset + halfMainW + 44;
	if (((main.Position.X.Scale * vp.X) + rightPos + panelW) > vp.X) then
		panel.Position = UDim2.new(main.Position.X.Scale, ((main.Position.X.Offset - halfMainW) - panelW) - 14, main.Position.Y.Scale, main.Position.Y.Offset);
	else
		panel.Position = UDim2.new(main.Position.X.Scale, rightPos, main.Position.Y.Scale, main.Position.Y.Offset);
	end
end;
Hub.ToggleSidePanel = function(self, forceState)
	local panel = self.State.SidePanel;
	if not panel then
		return;
	end
	local isOpen = not self.State.SidePanelOpen;
	if (forceState ~= nil) then
		isOpen = forceState;
	end
	self.State.SidePanelOpen = isOpen;
	if self.State.SideArrowLabel then
		self.State.SideArrowLabel.Text = (isOpen and "<") or ">";
	end
	if isOpen then
		self:UpdateSidePanelPosition();
		panel.Visible = true;
		self:Tween(panel, {BackgroundTransparency=0}, 0.2);
		task.spawn(function()
			task.wait(0.05);
			self:CloneLocalPlayerModel();
		end);
	else
		local tw = self:Tween(panel, {[LUAOBFUSACTOR_DECRYPT_STR_0("\237\136\118\31\200\155\122\1\193\141\65\6\206\135\102\4\206\155\112\26\204\144", "\116\175\233\21")]=1}, 0.15);
		tw.Completed:Connect(function()
			if not self.State.SidePanelOpen then
				panel.Visible = false;
			end
		end);
	end
end;
