Hub.SetFarmNoClip = function(self, on)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if on then
		if not char then
			return;
		end
		if hum then
			pcall(function()
				hum.PlatformStand = true;
			end);
		end
		for _, p in ipairs(char:GetDescendants()) do
			if (p:IsA("BasePart") and p.CanCollide) then
				if (self.AutoFarm.NoClipCache[p] == nil) then
					self.AutoFarm.NoClipCache[p] = p.CanCollide;
				end
				p.CanCollide = false;
			end
		end
	else
		if hum then
			hum.PlatformStand = false;
			hum.Sit = false;
			hum:SetStateEnabled(Enum.HumanoidStateType.Running, true);
			hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true);
			hum:ChangeState(Enum.HumanoidStateType.GettingUp);
			task.defer(function()
				if (hum and not self.AutoFarm.IsActive) then
					hum:ChangeState(Enum.HumanoidStateType.Running);
				end
			end);
		end
		if not self.Config.Toggles.NoClip then
			for p, v in pairs(self.AutoFarm.NoClipCache or {}) do
				if (p and p.Parent) then
					pcall(function()
						p.CanCollide = v;
					end);
				end
			end
			if char then
				for _, p in ipairs(char:GetDescendants()) do
					if p:IsA("BasePart") then
						if (p.Name == "HumanoidRootPart") then
							p.CanCollide = false;
						elseif ((p.Name == LUAOBFUSACTOR_DECRYPT_STR_0("\16\45\234\130", "\230\88\72\139")) or p.Name:find("Torso") or p.Name:find("Leg") or p.Name:find("Arm")) then
							p.CanCollide = true;
						end
					end
				end
			end
		end
		self.AutoFarm.NoClipCache = {};
	end
end;
Hub.ReturnToSurface = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if not root then
		return;
	end
	local upParams = RaycastParams.new();
	upParams.FilterType = Enum.RaycastFilterType.Exclude;
	upParams.IgnoreWater = true;
	upParams.FilterDescendantsInstances = {char};
	local res = self.Services.Workspace:Raycast(root.Position, Vector3.new(0, 400, 0), upParams);
	local y = (res and (res.Position.Y + 4)) or (self.AutoFarm.DownRefY and (self.AutoFarm.DownRefY + 4)) or (root.Position.Y + 16);
	pcall(function()
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position.X, y, root.Position.Z) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
				hum:ChangeState(Enum.HumanoidStateType.Running);
			end
		end);
	end
end;
Hub.ReleaseFarm = function(self)
	self.AutoFarm.HoldCF = nil;
	if self.AutoFarm.WasDown then
		self.AutoFarm.WasDown = false;
		self:ReturnToSurface();
	end
	self:SetFarmNoClip(false);
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if root then
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:SetStateEnabled(Enum.HumanoidStateType.Running, true);
		hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true);
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
				hum:ChangeState(Enum.HumanoidStateType.Running);
			end
		end);
	end
end;
