	while true do
		formatted, k = formatted:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\253\166\73\224\134\234\79\246\139\171\0\250\199\171\0\246", "\223\163\142\100"), LUAOBFUSACTOR_DECRYPT_STR_0("\199\71\143\244\234", "\216\226\118\163\209"));
		if (k == 0) then
