				if (desc:IsA("SpawnLocation") or (desc:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\201\44\110\71\219\44\111\86", "\34\139\77\29")) and string.find(desc.Name:lower(), "spawn"))) then
