			local pad = self:GetVotePad("VotePad1") or self:GetVotePad("VotePad2");
			if pad then
				if pad:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\146\241\14\81\25\177\226\9", "\73\208\144\125\52")) then
					targetPart = pad;
