				end
			end
		end
	end
	if not targetPart then
		for _, desc in ipairs(self.Services.Workspace:GetDescendants()) do
			if desc:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\25\252\139\220\201\60\92\200\43\248\131\196\201", "\171\74\140\234\171\167\112\51")) then
				targetPart = desc;
