		devType = LUAOBFUSACTOR_DECRYPT_STR_0("\155\178\29\77\171\184\30", "\38\223\215\110");
	end
	self.State.Device = {Type=devType,IsTouch=isTouch,[LUAOBFUSACTOR_DECRYPT_STR_0("\104\210\9\210\187\81\201\24", "\203\62\187\108\165")]=vp,IsMobile=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\212\123\74\55\125\251", "\176\153\20\40\94\17\158")),IsTablet=(devType == "Tablet"),IsConsole=(devType == "Console"),IsDesktop=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\140\54\168\88\209\167\35", "\165\200\83\219\51"))};
	return self.State.Device;
end;
Hub.GetAdaptiveWindowSize = function(self)
	local dev = self.State.Device or self:DetectDevice();
	local cam = self.Services.Workspace.CurrentCamera;
	local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720);
	if dev.IsMobile then
		local w = math.clamp(math.floor(vp.X * 0.94), 320, 560);
		local h = math.clamp(math.floor(vp.Y * 0.9), 280, 390);
		return UDim2.new(0, w, 0, h), UDim2.new(0, w + 30, 0, h + 30);
	elseif dev.IsTablet then
		local w = math.clamp(math.floor(vp.X * 0.85), 560, 680);
		local h = math.clamp(math.floor(vp.Y * 0.82), 380, 480);
		return UDim2.new(0, w, 0, h), UDim2.new(0, w + 40, 0, h + 40);
	else
		local w = math.min(720, math.floor(vp.X - 60));
		local h = math.min(500, math.floor(vp.Y - 60));
		return UDim2.new(0, w, 0, h), UDim2.new(0, w + 40, 0, h + 40);
	end
end;
